import{_ as t}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as i,o as a,c as r,al as o}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Return Mode (Fixed-Wing)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_modes_fw/return.md","filePath":"zh/flight_modes_fw/return.md"}'),n={name:"zh/flight_modes_fw/return.md"};function l(d,e,s,h,_,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="return-mode-fixed-wing" tabindex="-1">Return Mode (Fixed-Wing) <a class="header-anchor" href="#return-mode-fixed-wing" aria-label="Permalink to &quot;Return Mode (Fixed-Wing)&quot;">​</a></h1><img src="'+t+'" title="Position fix required (e.g. GPS)" width="30px"><p>The <em>Return</em> flight mode is used to <em>fly a vehicle to safety</em> on an unobstructed path to a safe destination, where it can land.</p><p>Fixed-wing vehicles use the <a href="./../flight_modes/return#rtl_type_1">Mission Landing/Rally Point</a> return type by default, and are expected to always have a mission with a landing pattern. With this configuration, return mode causes the vehicle to ascend to a minimum safe altitude above obstructions (if needed), fly to the start of the landing pattern defined in the mission plan, and then follow it to land.</p><p>Fixed-wing supports the <a href="./../flight_modes/return#return_types">other PX4 return types</a>, including home/rally point return, mission path and closest safe destination. The default type is recommended.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic - no user intervention is <em>required</em> to control the vehicle.</li><li>Mode requires a global 3d position estimate (from GPS or inferred from a <a href="./../ros/external_position_estimation#enabling-auto-modes-with-a-local-position">local position</a>). <ul><li>Flying vehicles can&#39;t switch to this mode without global position.</li><li>Flying vehicles will failsafe if they lose the position estimate.</li></ul></li><li>Mode requires home position is set.</li><li>Mode prevents arming (vehicle cannot be armed while this mode is selected).</li><li>遥控开关可以在任何无人机上更改飞行模式。</li><li>RC stick movement is ignored.</li></ul></div><h2 id="技术总结" tabindex="-1">技术总结 <a class="header-anchor" href="#技术总结" aria-label="Permalink to &quot;技术总结&quot;">​</a></h2><p>Fixed-wing vehicles use the <em>mission landing/rally point</em> return type by default. 无人机在该返航类型中：</p><ul><li>Ascends to a safe minimum return altitude defined by <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> (safely above any expected obstacles). The vehicle maintains its initial altitude if that is higher than the minimum return altitude. Note that return altitude cannot be configured using the &quot;cone&quot; parameter in fixed-wing vehicles.</li><li>Flies via a constant-altitude path to the destination, which will be the closest of the start of a <em>mission landing pattern</em> and any rally point, or the home location if no mission landing pattern or rally points are defined. The path is chosen to be the shortest horizontal <a href="./../flight_modes/return#geofence_awareness">geofence-aware path</a>.</li><li>If the destination is a <em>mission landing pattern</em> it will follow the pattern to land.</li><li>If the destination is a rally point or home it will descend to the descent altitude, and then loiter or land (depending on landing parameters).</li></ul><p>A fixed-wing vehicle is expected to use a landing pattern defined in a mission as the return destination, as this is the safest way to land automatically. This requirement is usually enforced by the <a href="#MIS_TKO_LAND_REQ">MIS_TKO_LAND_REQ</a> parameter.</p><p>A mission landing pattern consists of a <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_LAND_START" target="_blank" rel="noreferrer">MAV_CMD_DO_LAND_START</a>, one or more position waypoints, and a <a href="https://mavlink.io/en/messages/common.html#MAV_CMD_NAV_LAND" target="_blank" rel="noreferrer">MAV_CMD_NAV_LAND</a>.</p><p>When the destination is a rally point or the home location, on arrival the vehicle will rapidly descend to the altitude defined by <a href="#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a>, and by default circle above the destination indefinitely at radius <a href="#RTL_LOITER_RAD">RTL_LOITER_RAD</a>. The vehicle can be forced to land at the destination by changing <a href="#RTL_LAND_DELAY">RTL_LAND_DELAY</a> so it is not -1. In this case the vehicle will land in the same way as <a href="./../flight_modes_fw/land">Land mode</a>.</p><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_global_position_relaxed"><code>mode_req_global_position_relaxed</code></a> — Position measurement updates in a global coordinate frame but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_home_position"><code>mode_req_home_position</code></a> — Global home reference must be set</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position_relaxed"><code>mode_req_local_position_relaxed</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point but accepts poor accuracy</li><li><a href="./../flight_modes/mode_requirements#mode_req_prevent_arming"><code>mode_req_prevent_arming</code></a> — Mode prevents arming</li></ul><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><p>The RTL parameters are listed in <a href="./../advanced_config/parameter_reference#return-mode">Parameter Reference &gt; Return Mode</a>. If using a mission landing, only the <a href="#RTL_RETURN_ALT">RTL_RETURN_ALT</a> and <a href="#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a> are relevant. The others are relevant if the destination is a rally point or the home location.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><a id="RTL_TYPE"></a><a href="./../advanced_config/parameter_reference#RTL_TYPE">RTL_TYPE</a></td><td>Return type.</td></tr><tr><td><a id="RTL_RETURN_ALT"></a><a href="./../advanced_config/parameter_reference#RTL_RETURN_ALT">RTL_RETURN_ALT</a></td><td>Return altitude in meters (default: 60m)If already above this value the vehicle will return at its current altitude.</td></tr><tr><td><a id="RTL_DESCEND_ALT"></a><a href="./../advanced_config/parameter_reference#RTL_DESCEND_ALT">RTL_DESCEND_ALT</a></td><td>最小返航高度和无人机从较高的返航高度到减速或者停止的初始下降高度（默认： 30米）。</td></tr><tr><td><a id="RTL_LAND_DELAY"></a><a href="./../advanced_config/parameter_reference#RTL_LAND_DELAY">RTL_LAND_DELAY</a></td><td>Time to hover at <code>RTL_DESCEND_ALT</code> before landing (default: 0.5s) -by default this period is short so that the vehicle will simply slow and then land immediately. If set to -1 the system will loiter at <code>RTL_DESCEND_ALT</code> rather than landing. 延迟能够使你为起落架的展开部署配置时间（自动触发）。</td></tr><tr><td><a id="RTL_LOITER_RAD"></a><a href="./../advanced_config/parameter_reference#RTL_LOITER_RAD">RTL_LOITER_RAD</a></td><td>[Fixed-wing Only] The radius of the loiter circle (at <a href="#RTL_LAND_DELAY">RTL_LAND_DELAY</a>).</td></tr><tr><td><a id="MIS_TKO_LAND_REQ"></a><a href="./../advanced_config/parameter_reference#MIS_TKO_LAND_REQ">MIS_TKO_LAND_REQ</a></td><td>Specify whether a mission landing or takeoff pattern is required. Fixed wings generally require this.</td></tr></tbody></table><h2 id="另见" tabindex="-1">另见 <a class="header-anchor" href="#另见" aria-label="Permalink to &quot;另见&quot;">​</a></h2><ul><li><a href="./../flight_modes/return">Return Mode (Generic)</a></li><li><a href="./../flight_modes_mc/return">Return Mode (Multicopter)</a></li><li><a href="./../flight_modes_vtol/return">Return Mode (VTOL)</a></li></ul>',20)])])}const p=i(n,[["render",l]]);export{u as __pageData,p as default};
